class BatchIterator:
    """Yields fixed-size batches from a sequence of records."""

    def __init__(self, records, batch_size):
        self.records = records
        self.batch_size = batch_size
        self.index = 0

    def __iter__(self):
        # An iterator returns itself so it works in for-loops.
        return self

    def __next__(self):
        if self.index >= len(self.records):
            raise StopIteration  # signal exhaustion
        batch = self.records[self.index:self.index + self.batch_size]
        self.index += self.batch_size
        return batch


rows = [f"row-{i}" for i in range(7)]
for batch in BatchIterator(rows, batch_size=3):
    print(batch)

import itertools

def flatten(partitions):
    """Yield every record across many partitions as one flat stream."""
    for part in partitions:
        yield from part   # delegates iteration to each sub-iterable

def batched(iterable, n):
    """Group a stream into lists of size n using islice (Py<3.12)."""
    it = iter(iterable)
    while True:
        chunk = list(itertools.islice(it, n))
        if not chunk:
            return
        yield chunk

partitions = [range(0, 3), range(3, 6), range(6, 9)]
stream = flatten(partitions)

for batch in batched(stream, 4):
    print(batch)

# Lazily take the first 5 ids from an infinite counter
ids = (f"id-{n}" for n in itertools.count(1000))
print(list(itertools.islice(ids, 5)))
